/**
 * Browser-safe data of the Android device panel and its Remote error codes.
 * Generated by ttoken/apply-brand.mjs from ttoken/device/src/types.ts; edit it there.
 */

import type {} from '@deepseek-ai/dsh-typert-protocol'

/** One Android device or emulator that adb on the Host lists. */
export interface AndroidDevice {
  /** adb serial, such as `emulator-5554`, `R58N12345AB`, or `192.168.1.5:5555`. */
  readonly serial: string
  /** adb state: `device` when usable, `unauthorized` until the phone allows USB debugging, or another adb state. */
  readonly state: string
  /** Model name, such as `Pixel 9`; null when adb reports none. */
  readonly model: string | null
  /** How adb reaches the device. */
  readonly transport: 'usb' | 'emulator' | 'network'
}

/** The devices adb lists, or why adb could not run on the Host. */
export type AndroidDeviceList =
  | { readonly adb: 'ready'; readonly devices: readonly AndroidDevice[] }
  /**
   * adb is not installed, or could not start; the message says why, and `installable` says whether the panel can
   * install Google's platform-tools itself.
   */
  | { readonly adb: 'missing'; readonly message: string; readonly installable: boolean }

/** The Android Virtual Devices the emulator can start, or why the emulator could not run on the Host. */
export type AndroidEmulatorList =
  | { readonly emulator: 'ready'; readonly names: readonly string[] }
  /** The emulator is not installed, or could not start; the message says why. */
  | { readonly emulator: 'missing'; readonly message: string }

/** One screenshot of a device. */
export interface DeviceScreen {
  /** PNG image, base64. */
  readonly png: string
  /** Width in device pixels. */
  readonly width: number
  /** Height in device pixels. */
  readonly height: number
}

/** A navigation or hardware key. */
export type DeviceKey = 'back' | 'home' | 'recents' | 'enter' | 'delete' | 'power'

/** One input sent to a device; coordinates are device pixels of the current screen orientation. */
export type DeviceInput =
  | { readonly kind: 'tap'; readonly x: number; readonly y: number }
  | {
    readonly kind: 'swipe'
    readonly fromX: number
    readonly fromY: number
    readonly toX: number
    readonly toY: number
    /** Gesture length in milliseconds, 0 to 10,000. */
    readonly durationMs: number
  }
  /** Printable ASCII text, at most 500 characters, typed into the focused field. */
  | { readonly kind: 'text'; readonly text: string }
  | { readonly kind: 'key'; readonly key: DeviceKey }

declare module '@deepseek-ai/dsh-typert-protocol' {
  interface RemoteErrorDetailsMap {
    /** adb is not installed or could not start on the Host; the message says why. */
    'devicePanel/adb-unavailable': Record<string, never>
    /** adb failed, timed out, or answered with something other than the requested data; the message says why. */
    'devicePanel/adb-failed': Record<string, never>
    /** The serial, coordinates, or text cannot be sent to a device; the message names the problem. */
    'devicePanel/invalid-input': Record<string, never>
    /** The mirror window program is not installed or could not start on the Host; the message says why. */
    'devicePanel/mirror-unavailable': Record<string, never>
    /** The Android emulator is not installed or could not start on the Host; the message says why. */
    'devicePanel/emulator-unavailable': Record<string, never>
    /** Google's platform-tools could not be downloaded or unpacked on the Host; the message names the step. */
    'devicePanel/install-failed': Record<string, never>
  }
}
